import{_ as s,o as a,c as t,a3 as i}from"./chunks/framework.DNWyyI0w.js";const g=JSON.parse('{"title":"Writing a Custom Agent","description":"","frontmatter":{},"headers":[],"relativePath":"guides/writing-a-custom-agent.md","filePath":"guides/writing-a-custom-agent.md"}'),n={name:"guides/writing-a-custom-agent.md"};function o(l,e,p,r,d,h){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="writing-a-custom-agent" tabindex="-1">Writing a Custom Agent <a class="header-anchor" href="#writing-a-custom-agent" aria-label="Permalink to &quot;Writing a Custom Agent&quot;">​</a></h1><p>This guide builds a research specialist, puts it in a department, and gives its lead the ability to route work to it.</p><h2 id="_1-create-the-agent" tabindex="-1">1. Create the agent <a class="header-anchor" href="#_1-create-the-agent" aria-label="Permalink to &quot;1. Create the agent&quot;">​</a></h2><p>Ask PRIME, or call the tool:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>create_agent(</span></span>
<span class="line"><span>  name: &quot;research&quot;,</span></span>
<span class="line"><span>  description: &quot;Market and competitor research; produces sourced briefs.&quot;,</span></span>
<span class="line"><span>  department: &quot;Growth&quot;,</span></span>
<span class="line"><span>  permission: &quot;custom&quot;,</span></span>
<span class="line"><span>  tools: [&quot;Read&quot;, &quot;Grep&quot;, &quot;Glob&quot;, &quot;WebFetch&quot;, &quot;WebSearch&quot;]</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>That scaffolds <code>agents/research/</code> with an <code>AGENT.md</code>.</p><h2 id="_2-write-agent-md" tabindex="-1">2. Write <code>AGENT.md</code> <a class="header-anchor" href="#_2-write-agent-md" aria-label="Permalink to &quot;2. Write \`AGENT.md\`&quot;">​</a></h2><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Market and competitor research; produces sourced briefs.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">department: Growth</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lead: false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">permission: custom</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tools: [Read, Grep, Glob, WebFetch, WebSearch]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model: claude-opus-5</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">effort: medium</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">You are Saidi&#39;s research specialist.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## What you do</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Answer market, competitor, and pricing questions with sourced briefs. Every claim</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">carries its source URL inline.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## How you work</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Prefer primary sources: filings, changelogs, pricing pages, official docs.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> When two sources disagree, say so and give both.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Never state a number without a date attached to it.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## What you never do</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Never present a vendor&#39;s marketing copy as a finding.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Never guess at a figure you could not find. Say it is not public.</span></span></code></pre></div><p>The body is the persona prompt. The frontmatter is configuration:</p><table tabindex="0"><thead><tr><th>Key</th><th>Effect</th></tr></thead><tbody><tr><td><code>description</code></td><td>Shown in <code>list_agents</code>, and how PRIME decides to route to it</td></tr><tr><td><code>department</code></td><td>Groups it with its team</td></tr><tr><td><code>lead</code></td><td><code>true</code> gives it delegation tools over its department</td></tr><tr><td><code>permission</code></td><td><code>all</code> | <code>read-only</code> | <code>custom</code></td></tr><tr><td><code>tools</code></td><td>Exact allow-list when <code>permission: custom</code></td></tr><tr><td><code>model</code> / <code>profile</code> / <code>effort</code></td><td>Defaults; empty means inherit</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Write the description for the router, not for a human</p><p>PRIME picks an agent from its description. &quot;Market and competitor research; produces sourced briefs&quot; routes correctly. &quot;Helps with research stuff&quot; does not.</p></div><h2 id="_3-add-skills" tabindex="-1">3. Add skills <a class="header-anchor" href="#_3-add-skills" aria-label="Permalink to &quot;3. Add skills&quot;">​</a></h2><p>Skills are reusable procedures the agent can invoke.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_skill(agent: &quot;research&quot;, name: &quot;competitor-teardown&quot;, content: &quot;...&quot;)</span></span>
<span class="line"><span>import_skill(agent: &quot;research&quot;, url: &quot;https://example.com/skills/pricing-scan.md&quot;)</span></span></code></pre></div><p>They land in <code>agents/research/skills/</code>.</p><h2 id="_4-give-it-mcp-servers" tabindex="-1">4. Give it MCP servers <a class="header-anchor" href="#_4-give-it-mcp-servers" aria-label="Permalink to &quot;4. Give it MCP servers&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>add_mcp_server(agent: &quot;research&quot;, name: &quot;notion&quot;, config: { ... })</span></span></code></pre></div><p>This writes <code>agents/research/.mcp.json</code>. Only that agent gets those servers — this is the main reason to split a capability into its own agent rather than widening PRIME&#39;s belt.</p><h2 id="_5-make-a-lead" tabindex="-1">5. Make a lead <a class="header-anchor" href="#_5-make-a-lead" aria-label="Permalink to &quot;5. Make a lead&quot;">​</a></h2><p>Set <code>lead: true</code> on one agent in the department:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">description: Growth department lead. Routes research, content, and analysis work.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">department: Growth</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lead: true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">permission: all</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">---</span></span></code></pre></div><p>The lead is spawned with a different toolbelt:</p><ul><li><code>delegate_to_specialist</code> and <code>delegate_to_specialists</code> — scoped to the <em>other</em> agents in <code>Growth</code>, plus a prompt fragment naming the team.</li><li>Its own <code>delegate_to_project</code>, scoped to the department&#39;s projects, if any are mapped.</li></ul><p>A lead with no team members and no projects gets no delegation tools — there is nothing to route to.</p><h2 id="_6-give-it-memory" tabindex="-1">6. Give it memory <a class="header-anchor" href="#_6-give-it-memory" aria-label="Permalink to &quot;6. Give it memory&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>remember(scope: &quot;agent&quot;, name: &quot;research&quot;, facts: [</span></span>
<span class="line"><span>  &quot;Pricing pages for the three tracked competitors are archived monthly in the Growth Notion DB.&quot;,</span></span>
<span class="line"><span>  &quot;Never cite Crunchbase headcount figures — they lag by two quarters.&quot;</span></span>
<span class="line"><span>])</span></span></code></pre></div><p>Agent memory lives in <code>memory/agents/research.md</code> and is injected into every spawn.</p><h2 id="_7-test-it" tabindex="-1">7. Test it <a class="header-anchor" href="#_7-test-it" aria-label="Permalink to &quot;7. Test it&quot;">​</a></h2><p>Run it read-only first:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run_agent(agent: &quot;research&quot;, task: &quot;Summarise how the three tracked competitors price their team tier. Cite each source.&quot;)</span></span></code></pre></div><p>Check the report against the contract: verdict first, one line per thing asked, proof inline. If the agent returns a wall of narration, the persona needs tightening, not the task.</p><p>See also: <a href="/docs/concepts/agents-and-departments">Agents &amp; Departments</a> · <a href="/docs/concepts/modes-and-permissions">Modes &amp; Permissions</a></p>`,32)])])}const k=s(n,[["render",o]]);export{g as __pageData,k as default};
